(()=>{'use strict';const base='https://mowmatter-property.onrender.com/api/billing',esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function request(path,company,extra={}){const r=await fetch(base+path,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+MM.session.access_token},body:JSON.stringify({company_id:company,...extra}),signal:AbortSignal.timeout(30000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Billing is unavailable');return d}
window.showMowBilling=async company=>{const main=document.getElementById('main');main.innerHTML='<section class="card"><p class="eyebrow">MOW MATTER BILLING</p><h1>A plan for your next chapter.</h1><p role="status">Checking your subscription…</p></section>';try{const d=await request('/status',company);if(document.body.dataset.page!=='billing')return;const sub=d.subscription;main.innerHTML=`<section class="card"><p class="eyebrow">MOW MATTER BILLING</p><h1>A plan for your next chapter.</h1><p>Current plan: <strong>${esc(sub.plan==='starter'?'Solo Starter':sub.plan==='growth'?'Growth Route':'Scale & Crew')}</strong> · ${esc(sub.status.replaceAll('_',' '))}</p>${sub.cancel_at_period_end?'<p>Your subscription will end at the current billing period’s end.</p>':''}${new URLSearchParams(location.search).get('checkout')==='returned'?'<p role="status">Thanks for returning. Your plan updates after Stripe confirms payment. Use Refresh to check the latest status.</p>':''}${!d.checkout_enabled?'<p class="demo-bar">Checkout setup is being completed. You can keep using your current workspace; no payment will be taken here.</p>':''}<p><strong>${d.fee_percent}% Mow Matter fee</strong> on customer payments, plus Stripe processing fees.</p><p id="billing-message" role="status" aria-live="polite"></p><button class="button" id="manage-billing" ${!d.checkout_enabled||sub.status==='free'?'disabled':''}>Manage billing & invoices</button></section><section class="card"><h2>Solo Starter</h2><p>$0 / month · <strong>3.5% platform fee</strong></p><p>Start with up to 10 customers. Stripe processing fees are additional.</p></section><div class="split">${d.plans.map(p=>`<section class="card"><p class="eyebrow">${esc(p.name)}</p><h2>$${p.amount_cents/100}<small> / month</small></h2><p><strong>${p.fee_percent}% platform fee</strong> on customer payments, plus Stripe processing fees.</p><button class="button primary full" data-billing-plan="${esc(p.id)}" ${!d.checkout_enabled||sub.status!=='free'?'disabled':''}>Continue to secure checkout</button></section>`).join('')}</div><section class="card"><h2>Get paid for your lawn care.</h2><p>Homeowners pay your business. Stripe verifies your business and bank details; Mow Matter collects your plan’s percentage automatically.</p><button class="button primary" id="connect-payments" ${!d.connect_onboarding_enabled?'disabled':''}>Set up / finish payment onboarding</button><a class="button" href="financials.html">View accounting & payouts</a>${!d.connect_onboarding_enabled?'<p class="help">Stripe Connect activation is pending. No customer payments can be processed yet.</p>':''}</section><section class="card"><h2>Your billing, in your control.</h2><p>Subscriptions renew monthly until cancelled. Manage payment methods, invoices and cancellation through Stripe. Cancellation takes effect at the end of the paid billing period.</p><p class="help">These plans cover Mow Matter software. Customer payment availability depends on verified Stripe onboarding. The paid quoting add-on and automated usage charges are not enabled.</p></section>`;
const go=async(path,extra={})=>{const buttons=main.querySelectorAll('button'),disabled=[...buttons].map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);try{const r=await request(path,company,extra);const url=new URL(r.url);if(url.protocol!=='https:'||!['checkout.stripe.com','billing.stripe.com','connect.stripe.com'].includes(url.hostname))throw Error('Unexpected checkout destination');location.assign(url.href)}catch(e){document.getElementById('billing-message').textContent=e.message;buttons.forEach((b,i)=>b.disabled=disabled[i])}};
main.querySelectorAll('[data-billing-plan]').forEach(b=>b.onclick=()=>go('/checkout',{plan:b.dataset.billingPlan}));document.getElementById('manage-billing').onclick=()=>go('/portal');document.getElementById('connect-payments').onclick=()=>go('/connect/onboarding');}catch(e){main.innerHTML='<section class="card"><h1>Let’s reconnect billing.</h1><p id="billing-error" role="alert"></p><a href="billing.html" class="button primary">Try again</a></section>';document.getElementById('billing-error').textContent=e.message}};
window.showMowAccounting=async(company,target,jobs=[])=>{try{const d=await request('/accounting',company);if(document.body.dataset.page!=='financials')return;const money=(c,currency='usd')=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(c/100);const rows=d.transactions.map(t=>`<li><div><strong>${esc(t.description)}</strong><small>${esc(new Date(t.date*1000).toLocaleDateString())} · ${esc(t.status)}</small><p>Gross ${money(t.amount_cents,t.currency)} · Mow Matter ${money(t.platform_fee_cents,t.currency)} · Total deductions ${t.total_fee_cents===null?'pending':money(t.total_fee_cents,t.currency)} · Net ${t.net_cents===null?'pending':money(t.net_cents,t.currency)}${t.refunded_cents?' · Refunded '+money(t.refunded_cents,t.currency):''}</p></div></li>`).join('');target.innerHTML=`<div class="section-head"><h2>Customer payments & payouts</h2><a class="button" href="billing.html">Subscription & payment setup</a></div><p><strong>${esc(d.plan==='starter'?'Solo Starter':d.plan==='growth'?'Growth Route':'Scale & Crew')}</strong> · ${d.fee_percent}% platform fee, plus Stripe processing fees.</p><p>${d.connection?`Payments: ${d.connection.payments_ready?'verified':'verification pending'} · Bank payouts: ${d.connection.payouts_ready?'verified':'verification pending'}`:'Connect your payment account from Billing to accept homeowner payments.'}</p>${d.connection?'<a class="button" href="https://dashboard.stripe.com/" target="_blank" rel="noopener">Manage refunds, disputes & bank details in Stripe</a>':''}<form id="payment-link-form" class="form"><label>Completed visit<select name="job_id" required>${jobs.filter(j=>j.status==='completed'&&!j.cancelled_at&&j.price_cents>0).map(j=>`<option value="${esc(j.id)}">${esc(j.address)} · ${money(j.price_cents)}</option>`).join('')}</select></label><button class="button primary" ${!d.homeowner_payments_enabled||!d.connection?.payments_ready||!d.connection?.payouts_ready?'disabled':''}>Create secure customer payment link</button><label>Payment link<input id="customer-payment-link" readonly aria-label="Customer payment link"></label><p id="payment-link-message" role="status"></p></form><h3>Stripe balances</h3><p>${d.balances?['available','pending'].map(k=>`${k}: ${d.balances[k].map(b=>money(b.amount,b.currency)).join(', ')||'$0.00'}`).join(' · '):'No connected balance yet.'}</p><h3>Latest 50 customer transactions</h3><ul class="job-list">${rows||'<li>No processed customer payments yet.</li>'}</ul><h3>Latest 20 bank payouts</h3><ul class="job-list">${d.payouts.map(p=>`<li><strong>${money(p.amount_cents,p.currency)}</strong><span>${esc(p.status)} · expected ${esc(new Date(p.arrival_date*1000).toLocaleDateString())}</span></li>`).join('')||'<li>No bank payouts yet.</li>'}</ul><p class="help">Stripe balances and payouts are separate from manually recorded cash. Payout arrival dates are estimates. Transaction net values come from Stripe balance transactions; refunds and other adjustments affect the current balance.</p>`;target.querySelector('#payment-link-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),message=form.querySelector('[role="status"]');button.disabled=true;try{const r=await request('/payment-link',company,{job_id:new FormData(form).get('job_id')});const url=new URL(r.url);if(url.protocol!=='https:'||url.hostname!=='checkout.stripe.com')throw Error('Unexpected payment destination');form.querySelector('input').value=url.href;message.textContent='Link ready. Share it directly with your customer. No message was sent and no payment was taken.'}catch(err){message.textContent=err.message}finally{button.disabled=false}};}catch(e){target.innerHTML='<h2>Customer payments & payouts</h2><p role="alert"></p><a class="button" href="billing.html">Subscription & payment setup</a>';target.querySelector('p').textContent=e.message}};
})();
